    표5_매튜헨리: [
        {"영어원문":"O Lord of hosts, how long wilt thou not have mercy? — the angel of the Lord intercedes for Jerusalem, as Christ intercedes for His church.", "한국어번역":"만군의 여호와여 언제까지 긍휼히 여기지 아니하시렵나이까 — 여호와의 사자가 예루살렘을 위해 중보하시니, 그리스도가 교회를 위해 중보하심과 같다.", "핵심통찰":"여호와의 사자의 중보는 그리스도의 중보를 예표한다"},
        {"영어원문":"These threescore and ten years — the time prophesied by Jeremiah was now nearly fulfilled, yet the full restoration had not come.", "한국어번역":"이 칠십 년 — 예레미야가 예언한 기간이 거의 찼으나 아직 완전한 회복이 오지 않았다.", "핵심통찰":"약속의 때가 가까워졌으나 아직 완성되지 않은 상태"},
        {"영어원문":"It is no sin to be impatient for the fulfillment of God's promises when the time seems to be come.", "한국어번역":"때가 온 것 같을 때 하나님의 약속 성취를 초조하게 기다리는 것은 죄가 아니다.", "핵심통찰":"약속의 때가 되었다고 느낄 때 간절히 구하는 것은 정당하다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"언제까지입니까 - 여호와의 사자의 중보", "예화_적용":"그리스도는 지금도 우리를 위해 하나님 앞에서 중보하고 계신다"},
        {"대지":"서론", "내용":"여호와의 사자가 직접 하나님께 탄원한다. '언제까지 예루살렘을 긍휼히 여기지 않으시렵니까?' 이것은 놀라운 장면이다. 하나님의 사자가 백성의 고통을 자기 것으로 여기고 대신 울부짖고 있다. 이것이 바로 중보의 본질이다", "예화_적용":"당신의 고통을 아시고 대신 울어주시는 분이 계신다"},
        {"대지":"1대지: 만군의 여호와여 (권위 있는 탄원)", "내용":"만군의 여호와를 향한 직접적 탄원. 가장 높은 권위에 대한 직접 호소", "예화_적용":"우리의 기도는 만군의 여호와께 직접 닿는다"},
        {"대지":"2대지: 언제까지 긍휼히 여기지 않으시렵니까 (정당한 질문)", "내용":"고통 속에서 '언제까지'라고 묻는 것은 불경이 아니라 신뢰에서 나오는 정직한 기도", "예화_적용":"하나님 앞에서 솔직해지는 것이 참된 기도이다"},
        {"대지":"3대지: 칠십 년이 되었나이다 (때가 찬 호소)", "내용":"예레미야의 예언대로 70년이 거의 찼다. 약속의 때를 근거로 한 기도", "예화_적용":"하나님의 약속을 근거로 기도하는 것이 가장 강력한 기도이다"},
        {"대지":"결론", "내용":"여호와의 사자의 중보 후에 하나님이 '선한 말씀 위로하는 말씀'(13절)으로 응답하셨다. 중보기도는 응답받는다. 지금도 그리스도가 우리를 위해 아버지 앞에서 중보하고 계신다. 이 사실이 우리에게 무한한 위로와 확신을 준다", "예화_적용":"당신을 위해 중보하시는 분이 하나님 우편에 계신다 (롬 8:34)"}
    ],
