        {"교리":"중보의 원리", "설명":"천사가 백성을 위해 중보하고 하나님이 응답하시는 구조는 신약의 그리스도 중보를 예표", "관련구절":"롬 8:34, 히 7:25, 요일 2:1, 딤전 2:5"},
        {"교리":"말씀의 능력", "설명":"하나님의 선한 말씀은 단순한 위안이 아니라 실제적 변화를 일으키는 능력의 말씀", "관련구절":"히 4:12, 사 55:11, 렘 23:29, 시 107:20"}
