        {"영어원문":"When God says He is jealous for Zion, it is a word of comfort, for He will certainly act for those He is jealous for.", "한국어번역":"하나님이 시온을 위해 질투한다 하실 때 그것은 위로의 말씀이니 질투하시는 자를 위해 반드시 행동하실 것이기 때문이다.", "핵심통찰":"하나님의 질투는 행동으로 이어지는 사랑"}
