        {"교리":"영적 인식", "설명":"'눈을 들어 봄'은 하나님이 주시는 영적 시각을 받는 것. 자연적 눈으로는 볼 수 없는 영적 실재를 봄", "관련구절":"왕하 6:17, 엡 1:18, 시 119:18, 눅 24:31"},
        {"교리":"세상 권력의 한계", "설명":"네 뿔로 상징되는 세상 권력은 강해 보이지만 하나님의 주권 아래에 있으며 제한적", "관련구절":"단 2:44, 시 2:1-4, 사 40:15-17, 계 17:12-14"},
        {"교리":"사방의 공격", "설명":"숫자 4는 사방을 의미하며 모든 방향에서의 공격을 상징. 하나님의 백성은 완전히 포위된 것처럼 보이나 하나님이 보호하심", "관련구절":"시 3:6, 시 27:3, 시 125:2, 왕하 6:15-17"}
