        {"상황":"가족이 흩어져 고통받는 분", "성경원리":"유다와 이스라엘의 흩어짐을 하나님은 모두 아셨다. 하나도 잊지 않으셨다", "실제적용":"흩어진 가족에 대한 아픔을 하나님께 말씀드리라. 하나님은 모으시는 분이시다"},
        {"상황":"교회가 어려움을 겪고 있는 분", "성경원리":"예루살렘까지 헤침을 당했으나 하나님은 회복시키셨다", "실제적용":"교회의 어려움은 끝이 아니다. 하나님은 반드시 그의 교회를 세우신다"}
