        {"교리":"하나님의 충분한 대비", "설명":"네 뿔에 네 공장을 대응시키심은 하나님의 대비가 항상 충분함을 보여줌. 공격보다 방어가 부족하지 않음", "관련구절":"왕하 6:16, 롬 8:31, 사 54:17, 요일 4:4"},
        {"교리":"하나님의 주도적 계시", "설명":"'여호와께서 보이시기로'는 해결책이 인간의 발견이 아니라 하나님의 계시임을 강조", "관련구절":"마 16:17, 갈 1:12, 엡 3:3-5, 고전 2:10"},
        {"교리":"회복의 도구", "설명":"공장(장인)은 파괴가 아닌 건설의 도구. 하나님은 뿔(파괴)에 대해 공장(건설)으로 대응하심", "관련구절":"렘 24:6, 렘 31:4, 암 9:11, 행 15:16"}
