        {"교리":"풍성한 번영의 약속", "설명":"사람과 육축의 넘침은 물질적 영적 풍성함의 상징. 하나님 나라의 풍요", "관련구절":"겔 36:37-38, 사 49:19-20, 사 60:22, 욜 2:26"}
