        {"새찬송가":"73", "통일찬송가":"73", "제목":"영광의 왕께 문을 열라", "선정이유":"성소에서 일어나시는 영광의 왕"},
        {"새찬송가":"89", "통일찬송가":"89", "제목":"전능왕 오셔서", "선정이유":"일어나 행동하시는 전능하신 하나님"},
        {"새찬송가":"488", "통일찬송가":"395", "제목":"내 본향 가는 길", "선정이유":"하나님의 거룩한 처소를 향한 소망"}
