        {"대지":"결론", "내용":"하나님 앞에서 모르는 것은 부끄러운 일이 아니다. 겸손히 질문하라. 하나님은 묻는 자에게 답하신다. 당신의 겸손한 질문이 놀라운 답을 이끌어낼 것이다", "예화_적용":"겸손한 질문이 천국의 비밀을 여는 열쇠"}
