    표5_매튜헨리: [
        {"영어원문":"Knowest thou not what these be? No, my lord. — Honest acknowledgment of ignorance is the first step to divine instruction.", "한국어번역":"이것이 무엇인지 알지 못하느냐? 내 주여 알지 못합니다. — 무지에 대한 솔직한 인정이 신적 교훈의 첫걸음이다.", "핵심통찰":"솔직한 무지의 인정이 하나님의 가르침의 시작"},
        {"영어원문":"Those who confess they know not are in the best posture to be taught of God.", "한국어번역":"모르겠다고 고백하는 자가 하나님께 배우기에 가장 좋은 자세이다.", "핵심통찰":"모름을 인정하는 자가 가장 잘 배운다"},
        {"영어원문":"The question prepares the prophet for the great answer that follows — it is the Spirit, not might, that accomplishes God's work.", "한국어번역":"이 질문이 선지자를 뒤따르는 위대한 답을 위해 준비시키니 하나님의 일을 성취하는 것은 힘이 아닌 성령이다.", "핵심통찰":"무지의 인정이 '오직 나의 신으로'라는 위대한 답을 준비"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"내 주여 알지 못하나이다 - 무지의 고백과 지혜", "예화_적용":"모르겠다고 인정하는 용기가 하나님의 가르침을 여는 열쇠"},
        {"대지":"서론", "내용":"천사가 묻는다. '알지 못하느냐?' 스가랴가 답한다. '알지 못합니다.' 이 솔직한 고백 직후에 성경에서 가장 유명한 말씀 중 하나가 나온다. 비움이 채움의 전제이다", "예화_적용":"빈 컵만이 물을 받을 수 있듯 빈 마음만이 하나님의 말씀을 받을 수 있다"},
        {"대지":"1대지: 알지 못하느냐 (천사의 교육적 질문)", "내용":"비난이 아닌 교육을 위한 질문. 좋은 스승은 질문으로 가르친다", "예화_적용":"소크라테스의 산파법처럼 질문이 깨달음을 이끌어낸다"},
        {"대지":"2대지: 알지 못합니다 (솔직한 인정)", "내용":"선지자가 모른다고 솔직히 인정. 아는 체하지 않는 정직함", "예화_적용":"모른다고 인정하는 의사가 환자를 더 잘 돌보듯"},
        {"대지":"3대지: 위대한 답의 전제 (비움과 채움)", "내용":"이 무지의 고백 직후에 6절의 핵심 메시지가 주어짐. 비움이 채움의 전제", "예화_적용":"그릇을 비워야 새 물을 담을 수 있다"},
        {"대지":"결론", "내용":"하나님 앞에서 '알지 못합니다'라고 말하는 것은 약함이 아니라 지혜이다. 비워야 채워진다. 당신의 무지를 인정하라. 그때 하나님의 놀라운 가르침이 임할 것이다", "예화_적용":"가장 위대한 학자는 자기가 모르는 것을 아는 사람"}
    ],
