        {"항목":"마침의 약속", "내용":"같은 손이 기초를 놓았으니 같은 손이 완성할 것이라는 확실한 약속. BC 516년 성전 완공으로 성취", "목회적활용":"하나님의 약속은 반드시 성취된다"},
        {"항목":"보내신 줄 앎", "내용":"성전 완공을 통해 하나님이 선지자를 보내셨음을 알게 됨. 예언의 성취가 보내심의 증거", "목회적활용":"하나님의 약속이 성취될 때 그분의 역사를 확인하게 된다"}
