        {"항목":"악의 이동", "내용":"악이 단순히 소멸되는 것이 아니라 특정 장소로 옮겨짐. 고대 근동의 속죄양 의식과 유사한 구조 - 죄를 지고 광야로 보냄 (레 16:21-22)", "목회적활용":"죄의 제거에는 구체적 과정과 목적지가 있다"},
        {"항목":"어디로의 질문", "내용":"악의 최종 목적지를 묻는 것은 심판의 완결성에 대한 관심. 악이 정말로 완전히 제거되는지 확인하려는 질문", "목회적활용":"하나님의 심판에는 명확한 시작과 끝이 있다"}
