        {"구분":"악을 위한 집", "내용":"악이 영구적으로 안치될 처소가 지어짐", "그리스도연결":"마귀와 그 사자들을 위해 예비된 영원한 불 (마 25:41)"},
        {"구분":"제 처소에 머물게 됨", "내용":"악이 최종적으로 격리되어 더 이상 나오지 못함", "그리스도연결":"사탄이 불과 유황 못에 영원히 있게 됨 (계 20:10)"}
