        {"대지":"서론", "내용":"에바가 옮겨지는 최종 목적지가 밝혀진다. 시날 땅, 곧 바벨론이다. 바벨탑을 세운 그 땅, 이스라엘을 포로로 잡아간 그 땅으로 악이 되돌아간다. 그곳에 집이 지어지고 악이 영구히 안치된다. 하나님의 심판의 완결이다", "예화_적용":"범인이 결국 체포되어 감옥에 갇히듯 악은 반드시 최종 목적지에 이른다"},
        {"대지":"1대지: 시날 땅으로 (악의 근원지)", "내용":"시날은 바벨론, 하나님을 대적하는 모든 세력의 상징. 악이 자기 근원지로 돌아간다", "예화_적용":"악은 아무리 퍼져도 결국 자기 근원으로 돌아간다"},
        {"대지":"2대지: 집을 지으려 함이니라 (영구적 격리)", "내용":"악을 위한 집이 지어진다. 이것은 감옥이다. 악이 영구적으로 갇히는 장소", "예화_적용":"요한계시록의 불못은 악을 위해 예비된 영원한 감옥이다"},
        {"대지":"3대지: 제 처소에 머물게 되리라 (최종 안치)", "내용":"준공되면 악이 제 자리에 머문다. 더 이상 나오지 못한다. 심판의 완결", "예화_적용":"그리스도의 재림 때 악의 모든 문제가 최종적으로 해결된다"},
        {"대지":"결론", "내용":"악의 최종 목적지는 정해져 있다. 시날 땅에 영구히 갇힌다. 이것이 성경이 약속하는 하나님의 최종 심판이다. 그러므로 악에 절망하지 말라. 하나님이 반드시 승리하신다. 새 하늘 새 땅에는 악이 없다", "예화_적용":"하나님의 최종 승리를 믿고 소망 가운데 살라"}
