        {"새찬송가":"558", "통일찬송가":"455", "제목":"저 높은 곳을 향하여", "선정이유":"악이 제거된 하늘 본향을 향한 소망"},
        {"새찬송가":"551", "통일찬송가":"545", "제목":"저 건너 강 언덕 위에", "선정이유":"악이 없는 영원한 세계에 대한 소망"}
