        {"대지":"서론", "내용":"네 병거의 말 색깔이 밝혀진다. 붉은 말과 검은 말이 먼저 소개된다. 각각 전쟁과 기근을 상징하는 이 말들은 하나님의 심판이 다양한 방식으로 임함을 보여준다", "예화_적용":"역사 속의 전쟁과 기근은 우연이 아니라 하나님의 섭리 가운데 있다"},
        {"대지":"1대지: 홍마 - 전쟁의 심판 (유혈의 경고)", "내용":"붉은 말은 전쟁과 피흘림을 상징. 나라와 나라 사이의 분쟁도 하나님의 심판의 도구가 될 수 있다", "예화_적용":"전쟁의 참화 속에서도 하나님의 주권을 인식하라"},
        {"대지":"2대지: 흑마 - 기근의 심판 (결핍의 경고)", "내용":"검은 말은 기근과 재앙을 상징. 물질적 풍요가 사라지는 것도 하나님의 심판의 한 형태", "예화_적용":"풍요를 당연시하지 말고 하나님의 공급에 감사하라"},
        {"대지":"3대지: 질서 있는 배열 (계획적 심판)", "내용":"첫째, 둘째로 순서가 있다. 하나님의 심판은 무질서하지 않고 계획적이며 체계적이다", "예화_적용":"하나님의 모든 일에는 질서와 때가 있다"},
        {"대지":"결론", "내용":"홍마와 흑마의 환상은 하나님의 심판이 다양하고 확실함을 보여준다. 이 심판 앞에서 우리는 회개하고 하나님을 경외해야 한다", "예화_적용":"심판의 다양한 형태를 통해 하나님은 회개를 촉구하신다"}
