        {"대지":"서론", "내용":"세째 병거의 백마와 네째 병거의 어룽지고 건장한 말이 소개된다. 백마는 승리를, 건장한 말은 강력한 능력을 나타낸다. 하나님의 심판은 확실하고 그 결과는 승리이다", "예화_적용":"역사의 모든 전쟁과 재앙 뒤에 하나님의 승리가 있다"},
        {"대지":"1대지: 백마 (승리의 보증)", "내용":"백마는 고대부터 승리의 상징. 하나님의 심판은 단순한 파괴가 아니라 승리를 향한 과정", "예화_적용":"그리스도인의 삶에서 고난은 패배가 아니라 승리의 과정이다"},
        {"대지":"2대지: 어룽진 말 (복합적 심판)", "내용":"여러 색이 섞인 말은 다양한 재앙이 복합적으로 임함을 상징", "예화_적용":"한 가지 시련에 다른 시련이 겹칠 때도 하나님의 계획 안에 있다"},
        {"대지":"3대지: 건장한 말 (충분한 능력)", "내용":"힘센 말은 하나님의 능력이 충분함을 보여줌. 어떤 대적도 이길 수 있다", "예화_적용":"하나님의 능력은 우리가 상상하는 것 이상으로 충분하다"},
        {"대지":"결론", "내용":"네 종류의 말들이 모두 출동한다. 하나님의 심판은 완전하고 그 능력은 충분하며 그 결과는 승리이다. 이 하나님 편에 서는 것이 가장 지혜로운 선택이다", "예화_적용":"승리하시는 하나님 편에 서라"}
