        {"대지":"서론", "내용":"놀라운 환상을 본 스가랴가 천사에게 질문한다. 내 주여 이것들이 무엇이니이까. 보았지만 이해하지 못한 것을 겸손히 질문하는 선지자의 모습에서 우리는 배움의 올바른 자세를 발견한다", "예화_적용":"성경을 읽으면서 질문하지 않으면 깊은 이해에 도달할 수 없다"},
        {"대지":"1대지: 내 주여 (겸손한 태도)", "내용":"아도니(내 주여)라는 존칭은 배우는 자의 겸손을 보여줌. 교만한 자에게는 진리가 닫힌다", "예화_적용":"겸손한 마음이 하나님의 말씀을 받는 토양이다"},
        {"대지":"2대지: 이것들이 무엇이니이까 (적극적 질문)", "내용":"보았지만 모르면 질문한다. 적극적 질문이 영적 성장의 열쇠", "예화_적용":"설교를 듣고 질문하는 것이 더 깊은 이해의 시작이다"},
        {"대지":"3대지: 천사의 대답을 기다림 (배움의 자세)", "내용":"질문 후 대답을 기다리는 인내. 하나님의 응답은 반드시 온다", "예화_적용":"기도 후에 하나님의 응답을 기다리는 인내가 필요하다"},
        {"대지":"결론", "내용":"스가랴의 질문은 우리에게 배움의 올바른 자세를 가르친다. 겸손하게 질문하고 인내하며 기다리면 하나님은 반드시 이해를 주신다", "예화_적용":"구하라 그러면 너희에게 주실 것이요 (마 7:7)"}
