        {"대지":"서론", "내용":"환상의 시간이 끝나고 하나님이 직접 말씀하신다. 여호와의 말씀이 내게 임하여. 이 간단한 문장이 이어질 메시아 예언의 문을 연다. 가장 위대한 계시는 가장 단순한 시작에서 출발한다", "예화_적용":"성경의 가장 위대한 진리도 하나님이 말씀하시다로 시작된다"},
        {"대지":"1대지: 여호와의 (말씀의 근원)", "내용":"말씀의 근원이 여호와이시다. 인간의 생각이 아닌 하나님의 계시", "예화_적용":"성경이 다른 책과 다른 이유는 그 저자가 하나님이시기 때문이다"},
        {"대지":"2대지: 말씀이 (살아있는 계시)", "내용":"데바르(말씀)는 단순한 정보가 아니라 능력과 생명을 가진 살아있는 실체", "예화_적용":"성경을 읽을 때 살아있는 하나님의 음성을 듣고 있음을 기억하라"},
        {"대지":"3대지: 내게 임하여 (개인적 만남)", "내용":"하나님의 말씀이 개인에게 직접 임한다. 보편적 진리이면서 개인적 만남", "예화_적용":"성경은 모두를 위한 말씀이면서 동시에 나에게 직접 하시는 말씀이다"},
        {"대지":"결론", "내용":"하나님이 말씀하신다. 이 사실이 모든 것을 바꾼다. 환상의 상징을 넘어 구체적 행동의 명령이 이어진다. 하나님의 말씀에 귀를 기울이라", "예화_적용":"하나님이 말씀하시는 순간 모든 것이 달라진다"}
