        {"대지":"서론", "내용":"만군의 여호와께서 놀라운 예언을 선포하신다. 순이라 이름하는 사람이 돋아나서 여호와의 전을 건축하리라. 이것은 구약의 가장 명확한 메시아 예언 중 하나이다. 다윗의 뿌리에서 새싹이 돋아나 하나님의 참된 성전을 세우실 것이다", "예화_적용":"마른 땅에서 올라온 싹이 온 세상을 덮는 나무가 되었다"},
        {"대지":"1대지: 순이라 이름하는 사람 (메시아의 칭호)", "내용":"체마흐(순/새싹)는 사 4:2, 렘 23:5에도 등장하는 메시아 칭호. 다윗의 뿌리에서 돋아나는 의로운 왕", "예화_적용":"베들레헴의 마구간에서 태어나신 아기가 만왕의 왕이시다"},
        {"대지":"2대지: 자기 곳에서 돋아나서 (겸손한 출현)", "내용":"화려한 곳이 아닌 자기 곳에서 조용히 돋아남. 메시아의 겸손한 출현", "예화_적용":"나사렛에서 무슨 선한 것이 나겠느냐 (요 1:46) - 그러나 그곳에서 나왔다"},
        {"대지":"3대지: 여호와의 전을 건축하리라 (성전의 건축자)", "내용":"메시아가 세우실 성전은 돌과 나무의 성전이 아니라 산 돌로 세워지는 영적 성전 - 교회", "예화_적용":"우리가 하나님의 성전이며 그리스도가 건축자이시다"},
        {"대지":"결론", "내용":"순이라 이름하는 분이 오셨다. 나사렛의 미천한 곳에서 돋아나 십자가와 부활을 통해 하나님의 영적 성전 교회를 세우셨다. 이 분이 우리의 왕이시며 대제사장이시다", "예화_적용":"이 땅에서 가장 위대한 건축은 그리스도가 세우시는 교회이다"}
