        {"원어":"לְחַלּוֹת (르할로트)", "의미_문법":"은혜를 구하다 - 동사 피엘 부정사. 하나님의 얼굴을 구함", "설교포인트":"하나님의 은혜를 간절히 구하는 것이 예배의 시작"},
        {"원어":"אֶת־פְּנֵי יְהוָה (에트 프네이 아도나이)", "의미_문법":"여호와의 얼굴을 - 명사. 하나님의 임재를 구함", "설교포인트":"하나님의 얼굴을 구하는 것이 참된 예배의 본질"}
