        {"항목":"사레셀과 레겜멜렉", "내용":"바빌론식 이름을 가진 유대인들로 포로기의 문화적 영향을 보여줌. 그럼에도 여호와께 나아온 신앙인", "목회적활용":"문화적 환경이 달라도 하나님을 찾는 마음은 변하지 않는다"},
        {"항목":"사절단 파견의 목적", "내용":"70년간 지켜온 금식의 지속 여부를 공식적으로 묻기 위해 대표단을 파견. 성전 재건이 진행 중이므로 금식의 필요성에 대한 질문이 자연스러움", "목회적활용":"변화하는 상황에서 하나님의 뜻을 구하는 것이 지혜이다"}
