        {"항목":"70년간의 금식 전통", "내용":"바빌론 포로기(BC 586)부터 성전 재건 시기(BC 518)까지 약 68년간 지속된 금식. 성전이 재건되고 있으므로 금식 지속 여부가 자연스러운 질문", "목회적활용":"환경이 변하면 신앙의 형식도 재평가할 수 있다"},
        {"항목":"제사장과 선지자에게 질문", "내용":"성전에서 봉사하는 제사장들과 하나님의 말씀을 전하는 선지자들에게 공식적으로 질문. 구약 시대의 영적 자문 체계", "목회적활용":"영적 질문에 대해 하나님이 세우신 통로를 통해 답을 구한다"}
