        {"항목":"포로 귀환 후의 생활", "내용":"귀환한 유대인들의 일상이 자기 중심으로 흘러가고 있었음. 학개도 비슷한 지적을 함 (학 1:4,9)", "목회적활용":"영적 부흥 시기에도 자기 중심적 삶의 유혹은 계속된다"},
        {"항목":"수사적 반문", "내용":"'아니냐'라는 반문 형식은 부정할 수 없는 사실을 지적. 변명의 여지를 주지 않는 하나님의 직설적 꾸짖음", "목회적활용":"하나님의 꾸짖음은 사랑에서 나온 것이며 정직한 성찰을 요구한다"}
