        {"대지":"서론", "내용":"하나님의 진단이 날카롭다. 금식이 자기를 위한 것이었을 뿐 아니라, 먹고 마시는 일상도 자기를 위한 것이었다. 종교와 일상 모두에서 하나님이 빠져 있었다. 이것이 이스라엘의 진짜 문제였다", "예화_적용":"하나님 없는 경건은 자기만족이고, 하나님 없는 일상은 공허함이다"},
        {"대지":"1대지: 먹으며 마심 (일상의 영역)", "내용":"하나님은 금식만이 아니라 먹고 마시는 가장 기본적 일상까지 물으신다. 하나님의 관심은 일상 전체에 미친다", "예화_적용":"영적 삶은 교회에서만이 아니라 식탁에서, 직장에서, 일상에서 시작된다"},
        {"대지":"2대지: 자기를 위하여 (자기 중심의 폭로)", "내용":"금식도 자기를 위해, 식사도 자기를 위해. 삶 전체가 자기 중심으로 돌아가고 있었다", "예화_적용":"내 삶의 중심에 누가 있는가? 자기인가 하나님인가? 정직한 점검이 필요하다"},
        {"대지":"3대지: 아니냐 (부인할 수 없는 사실)", "내용":"수사적 반문으로 변명의 여지를 차단. 하나님 앞에서 자기기만은 통하지 않는다", "예화_적용":"하나님 앞에 정직해지자. 자기를 속이는 것이 가장 위험한 죄이다"},
        {"대지":"결론", "내용":"오늘 하루 먹고 마시는 것부터 하나님을 위하여 하라. 먹든지 마시든지 무엇을 하든지 다 하나님의 영광을 위하여 하라. 이것이 참된 영성의 시작이다", "예화_적용":"고전 10:31의 말씀을 식탁 위에, 직장 책상 위에, 삶의 모든 곳에 새기라"}
