        {"구분":"형통에서 황폐로의 전환", "내용":"불순종으로 인해 형통한 땅이 황무하게 됨", "그리스도연결":"예루살렘의 멸망을 예언하시며 우시는 예수님 (눅 19:41-44)"},
        {"구분":"말씀에 청종하라는 촉구", "내용":"이전 선지자들의 외침을 다시 상기시킴", "그리스도연결":"내 말을 듣고 행하는 자는 반석 위에 집을 지은 자 (마 7:24)"}
