    표5_매튜헨리: [
        {"영어원문":"They made their hearts as an adamant stone, the hardest of all stones, which nothing will make an impression upon.", "한국어번역":"그들은 마음을 금강석같이 만들었으니 모든 돌 중 가장 단단하여 어떤 것도 자국을 낼 수 없는 것이다.", "핵심통찰":"완고한 마음은 하나님의 말씀조차 뚫지 못하게 한다"},
        {"영어원문":"The law and the prophets were all sent by the Spirit of God, and therefore the contempt of them was a contempt of the Holy Spirit.", "한국어번역":"율법과 선지자 모두 하나님의 영으로 보내진 것이므로 그것을 멸시하는 것은 성령을 멸시하는 것이다.", "핵심통찰":"하나님의 말씀을 거부하는 것은 성령을 거역하는 것"},
        {"영어원문":"Therefore came great wrath from the Lord of hosts—punishments proportioned to the provocations.", "한국어번역":"그러므로 만군의 여호와로부터 큰 진노가 나왔으니 도발에 비례하는 형벌이었다.", "핵심통찰":"심판의 크기는 불순종의 크기에 비례한다"}
    ],
