        {"상황":"완고한 성격을 가진 분", "성경원리":"마음의 완고함은 하나님과의 관계를 단절시킨다", "실제적용":"고집과 신념을 구분하라. 하나님의 말씀 앞에서는 겸손히 자신을 내려놓아야 한다"}
