        {"대지":"2대지: 듣지 아니하였은즉 (인간의 거부)", "내용":"하나님의 반복된 부르심에도 듣기를 거부한 이스라엘", "예화_적용":"하나님의 부르심을 거부하는 것은 자신의 미래를 거부하는 것이다"},
        {"대지":"3대지: 그들이 불러도 내가 듣지 아니하고 (결과적 침묵)", "내용":"위기에 하나님을 부르짖으나 응답이 없음. 관계 거부의 당연한 결과", "예화_적용":"위기의 기도보다 평소의 순종이 중요하다. 지금 하나님의 음성에 응답하라"},
        {"대지":"결론", "내용":"하나님의 부르심에 응답할 수 있는 오늘이 은혜의 날이다. 내일은 알 수 없다. 지금 하나님의 음성을 듣고 응답하자", "예화_적용":"보라 지금은 은혜 받을 만한 때요 구원의 날이라 (고후 6:2)"}
