        {"항목":"노인의 사회적 위치", "내용":"고대 이스라엘에서 노인은 지혜와 축복의 상징. 노인이 길거리에 앉아 있다는 것은 사회가 안정되고 평화롭다는 의미", "목회적활용":"어른을 공경하고 노인이 편안한 사회가 하나님이 축복하신 사회"},
        {"항목":"장수의 축복", "내용":"구약에서 장수는 하나님의 축복의 대표적 표현(출 20:12, 신 5:33). 전쟁과 역병으로 수명이 단축되었던 것이 회복됨", "목회적활용":"생명의 보존과 장수는 하나님의 은혜임을 감사하라"}
