        {"영어원문":"The increase of children is a token of God's favour and the city's prosperity.", "한국어번역":"아이들의 증가는 하나님의 은총과 도시의 번영의 표징이다.", "핵심통찰":"다음 세대의 풍성함이 하나님의 축복의 증거"},
        {"영어원문":"Old men and children together—this is the picture of a city at perfect peace and happiness.", "한국어번역":"노인과 어린이가 함께 - 이것이 완전한 평화와 행복의 도시의 모습이다.", "핵심통찰":"모든 세대가 평화롭게 공존하는 것이 참된 행복"}
