        {"교리":"하나님의 징계", "설명":"'내가 뭇 사람으로 서로 치게 하였음이어니와' - 내부 갈등도 하나님의 징계의 일부임을 인정. 하나님의 주권적 통치", "관련구절":"삿 2:14-15, 사 19:2, 학 2:17, 호 4:1-3"},
        {"교리":"과거와 현재의 대비", "설명":"'그 날 전에는'이라는 표현으로 과거의 어려움을 상기시킨 후 현재/미래의 축복과 대비. 변화의 주체는 하나님", "관련구절":"학 2:15-19, 말 3:10-12, 시 126:1-6, 사 43:18-19"}
