    표8_상담적용: [
        {"상황":"노력해도 결실이 없어 좌절하는 분", "성경원리":"하나님의 축복 없이는 사람도 짐승도 삯을 얻지 못했다. 하나님의 축복이 결실의 근원", "실제적용":"노력에만 의존하지 말고 하나님의 축복을 구하라. 먼저 하나님 나라를 구하라 (마 6:33)"},
        {"상황":"공동체의 갈등으로 고통받는 분", "성경원리":"하나님이 서로 치게 하셨다는 것은 내부 갈등도 영적 원인이 있을 수 있음을 시사", "실제적용":"갈등의 원인을 사람에게만 돌리지 말고 영적 원인도 성찰하라. 하나님 앞에 회개하고 화해를 구하라"},
        {"상황":"현재의 축복에 감사함이 없는 분", "성경원리":"과거의 어려움을 기억하면 현재의 축복에 감사하게 된다", "실제적용":"과거의 어려웠던 시절을 기억하라. 그리고 지금 누리고 있는 것들에 감사하라"}
    ],
