        {"원어":"טַל (탈)", "의미_문법":"이슬 - 명사. 건기에 수분을 공급하는 하늘의 선물", "설교포인트":"하늘에서 내리는 이슬은 하나님의 보이지 않는 축복"},
        {"원어":"אֶת־שְׁאֵרִית (에트 쉐에리트)", "의미_문법":"남은 자를 - 명사. 포로 귀환 공동체", "설교포인트":"소수의 남은 자가 하나님의 풍성한 축복을 누린다"}
