        {"항목":"농업적 축복", "내용":"포도나무, 땅의 산물, 하늘의 이슬은 팔레스타인 농업의 3대 축복 요소. 신명기 28장의 순종에 대한 축복과 동일", "목회적활용":"하나님의 축복은 삶의 구체적 영역에서 경험된다"},
        {"항목":"학개의 예언과 연결", "내용":"학개 2:19의 '이 날부터 내가 복을 주리라'와 동일한 메시지. 성전 재건에 대한 축복의 약속", "목회적활용":"하나님의 일에 우선순위를 두면 물질적 축복도 따라온다"}
