        {"대지":"2대지: 포도나무와 땅과 하늘 (자연의 축복)", "내용":"포도나무, 땅, 하늘이 모두 축복에 참여. 삶의 모든 영역에서 풍요가 넘침", "예화_적용":"하나님의 축복은 삶의 한 영역이 아니라 모든 영역에 미친다"},
        {"대지":"3대지: 남은 백성에게 (은혜의 수여)", "내용":"'내가 누리게 하리라' - 축복의 주체는 하나님. 남은 자가 누리는 것은 은혜", "예화_적용":"풍요를 자기 노력의 결과로만 보지 말고 하나님의 은혜로 감사하라"},
        {"대지":"결론", "내용":"하나님이 축복하시면 포도나무가 열매를 맺고, 땅이 산물을 내고, 하늘이 이슬을 내린다. 이 풍성한 축복은 하나님의 은혜이며 순종의 열매이다", "예화_적용":"하나님의 일에 우선순위를 두라. 그러면 이 모든 것을 너희에게 더하시리라 (마 6:33)"}
