        {"교리":"두려움과 믿음", "설명":"'두려워 말라'는 구약에서 가장 많이 반복되는 명령 중 하나. 하나님의 약속이 두려움을 이기는 근거", "관련구절":"사 41:10, 수 1:9, 시 23:4, 사 43:1"},
        {"교리":"아브라함 언약의 성취", "설명":"'축복이 되게 하리라'는 창 12:2-3의 아브라함 언약의 반향. 이스라엘을 통해 열방이 축복받으리라는 약속", "관련구절":"창 12:2-3, 창 22:18, 갈 3:8-9, 행 3:25"}
