        {"대지":"서론", "내용":"이스라엘은 열국에서 저주의 본보기였다. 포로로 끌려간 비참한 민족. 그러나 하나님은 선언하신다 - '너희를 축복이 되게 하리라.' 저주에서 축복으로, 이것이 하나님의 반전이다", "예화_적용":"인생의 가장 어두운 시점이 하나님의 가장 큰 반전의 시작점이 될 수 있다"},
        {"대지":"1대지: 저주가 되었었으나 (과거의 비참)", "내용":"열국 가운데 저주의 본보기. 다른 민족이 '이스라엘처럼 되지 말자'고 말하던 시절", "예화_적용":"과거의 실패가 아무리 참혹해도 하나님의 은혜 앞에서는 극복 가능하다"},
        {"대지":"2대지: 축복이 되게 하리니 (미래의 영광)", "내용":"저주의 자리에서 축복의 통로로. 아브라함 언약의 성취", "예화_적용":"하나님은 당신을 저주의 자리에 두지 않으신다. 축복의 통로로 세우실 것이다"},
        {"대지":"3대지: 두려워 말고 손을 견고히 (담대한 실천)", "내용":"약속을 받은 자의 자세 - 두려움을 버리고 담대히 행동하라", "예화_적용":"하나님의 약속이 있으니 두려워하지 말고 담대히 나아가라"},
        {"대지":"결론", "내용":"당신의 과거가 어떠했든 하나님은 그것을 축복으로 바꾸실 수 있다. 저주를 축복으로, 실패를 성공으로, 슬픔을 기쁨으로. 이것이 우리 하나님의 능력이다", "예화_적용":"과거를 돌아보며 절망하지 말고, 약속을 바라보며 소망하라"}
