        {"대지":"서론", "내용":"하나님은 자신이 '미워하는 것'을 분명히 말씀하신다. 심중의 악한 도모, 거짓 맹세 - 이것들을 하나님이 적극적으로 미워하신다. 사랑의 하나님이 동시에 악을 미워하시는 거룩한 하나님이시다", "예화_적용":"하나님의 사랑을 알려면 하나님의 미움도 알아야 한다"},
        {"대지":"1대지: 심중에 해하기를 도모함 (마음의 죄)", "내용":"행동 이전의 마음속 악한 계획. 하나님은 마음까지 보신다", "예화_적용":"행동으로 옮기지 않아도 마음속의 악한 의도는 이미 죄이다"},
        {"대지":"2대지: 거짓 맹세 (하나님의 이름 모독)", "내용":"하나님의 이름을 걸고 거짓을 행함. 신앙을 이용한 기만", "예화_적용":"하나님의 이름으로 자기 이익을 도모하는 것은 가장 큰 모독이다"},
        {"대지":"3대지: 나의 미워하는 것 (하나님의 거룩한 분노)", "내용":"하나님이 적극적으로 미워하신다는 선언. 악에 대한 무관용", "예화_적용":"하나님이 미워하시는 것을 우리도 미워하는 것이 경건이다 (롬 12:9)"},
        {"대지":"결론", "내용":"하나님이 미워하시는 것을 알았으니 피하라. 마음을 깨끗이 하고, 진실만을 말하며, 하나님의 이름을 거룩히 여기라", "예화_적용":"하나님이 사랑하시는 것을 사랑하고, 미워하시는 것을 미워하라"}
