        {"항목":"이스라엘의 사명", "내용":"13절에서 '축복이 되게 하리라'던 약속의 구체화. 이스라엘이 열방의 축복의 통로가 됨", "목회적활용":"하나님의 백성은 받은 축복을 세계에 나누는 통로"}
