        {"대지":"2대지: 많은 성읍의 거민 (세계적 규모)", "내용":"'많은 성읍'은 세계적 규모의 회심. 소수가 아닌 대규모 운동", "예화_적용":"복음은 세계의 모든 도시와 마을에 전해질 것이다"},
        {"대지":"3대지: 올 것이라 (자발적 순례)", "내용":"강제가 아닌 자발적으로 하나님을 찾아옴. 은혜의 매력에 이끌려", "예화_적용":"참된 전도는 강제가 아니라 하나님의 은혜의 매력으로 사람을 이끄는 것"},
        {"대지":"결론", "내용":"하나님의 나라는 온 세계로 확장된다. 우리는 이 세계적 비전의 참여자이다. 모든 민족이 하나님을 찾아오는 날을 기대하며 복음을 전하자", "예화_적용":"선교는 명령이기 전에 하나님의 비전이다. 이 비전에 동참하라"}
