        {"교리":"신앙의 전염성", "설명":"한 성읍의 열정이 다른 성읍으로 전파. 참된 신앙은 자연스럽게 전파되는 전염성을 가짐", "관련구절":"행 2:47, 살전 1:7-8, 행 13:44, 행 17:6"},
        {"교리":"하나님 추구의 공동체적 성격", "설명":"개인이 아닌 공동체가 함께 하나님을 찾음. 신앙은 개인적이면서 동시에 공동체적", "관련구절":"시 34:3, 시 95:1, 히 10:24-25, 마 18:20"}
