        {"대지":"결론", "내용":"두로의 요새와 재물은 하나님의 심판을 막지 못했다. 참된 보장은 하나님뿐이시다. 물질이 아닌 하나님을 의지하는 삶을 선택하자", "예화_적용":"내 인생의 보장(요새)은 무엇인가? 하나님이 아닌 것에 의지하고 있지 않은가?"}
