        {"교리":"불의 심판", "설명":"불로 삼키움은 완전한 소멸적 심판을 상징. 두로의 모든 자랑이 불에 타 사라짐", "관련구절":"히 12:29, 신 4:24, 말 4:1, 벧후 3:10"},
        {"교리":"해양 권력의 종말", "설명":"바다 권세를 치심은 인간이 의지하는 최강의 힘도 무너뜨리시는 하나님의 능력을 보여줌", "관련구절":"시 89:9, 시 107:25-29, 출 15:4-5, 계 21:1"}
