        {"구절":"마 26:28", "연결점":"새 언약의 피 - 죄사함을 위한 것", "구분":"신약"},
        {"구절":"히 9:12", "연결점":"자기 피로 영원한 속죄를 이루심", "구분":"신약"},
        {"구절":"눅 4:18", "연결점":"포로 된 자에게 자유를 주며", "구분":"신약"},
        {"구절":"엡 2:1-6", "연결점":"죄로 죽은 우리를 살리심", "구분":"신약"}
