        {"항목":"제사적 이미지", "내용":"동이와 제단 모퉁이는 제사 때 피를 받고 뿌리는 도구와 장소. 전쟁의 승리가 하나님께 드리는 제사로 묘사됨", "목회적활용":"승리도 하나님께 드리는 예배이다"}
