        {"항목":"세대를 잇는 기쁨", "내용":"자손이 보고 기뻐함. 회복의 기쁨이 다음 세대에까지 전해짐", "목회적활용":"하나님의 은혜의 기쁨은 세대를 넘어 전달된다"}
