        {"교리":"하나님의 이름으로 사는 삶", "설명":"이름을 받들어 왕래함은 일상 전체를 하나님의 이름 아래 사는 것. 예배와 삶의 통합", "관련구절":"골 3:17, 잠 18:10, 미 4:5, 시 20:7"},
        {"교리":"예언의 확실성", "설명":"'여호와의 말이니라'로 마무리되는 약속의 확실성. 하나님의 말씀은 반드시 성취됨", "관련구절":"민 23:19, 사 55:11, 히 6:18, 딤후 2:13"}
